import torch

def gen_inputs(ctx, device):
    dtype = getattr(torch, ctx['operands__dtype'])
    operands = [
        torch.randn(tuple(shape), dtype=dtype, device=device)
        for shape in ctx['operands__shape']
    ]
    return {'operands': operands}

def run(equation, operands):
    return torch.einsum(equation, *operands)


def run_correctness(equation, operands):
    reference_operands = [
        value.float()
        if value.dtype in (torch.float16, torch.bfloat16)
        else value
        for value in operands
    ]
    output = torch.einsum(equation, *reference_operands)
    return output.to(operands[0].dtype)
